// Rejects anyone who doesn't know GHL_WEBHOOK_SECRET.
// Accepted in the X-GHL-Secret header (Custom Webhook action) or as "secret" in Custom Data (plain Webhook action).
const j = $input.first().json;
const expected = $env.GHL_WEBHOOK_SECRET || '';
const received = j.headers?.['x-ghl-secret'] || j.body?.customData?.secret || j.body?.secret || '';
if (expected && received !== expected) {
  throw new Error('Unauthorized: bad or missing secret');
}
return $input.all();

// Works with both GHL actions:
//  - Custom Webhook: your own JSON body (name, email, booked, ...)
//  - plain Webhook : GHL sends the contact (full_name, email, phone) + your Custom Data under customData
const raw = $input.first().json.body || {};
const b = { ...raw, ...(raw.customData || {}) };
b.name = b.name || raw.full_name || [raw.first_name, raw.last_name].filter(Boolean).join(' ');
b.email = b.email || raw.email;
b.phone = b.phone || raw.phone;

const isBlank = (v) => {
  if (v == null) return true;
  const s = String(v).trim();
  return s === '' || s === 'null' || s === 'undefined' || s === 'None';
};

// GHL escapes real newlines in merge fields as the literal "\n". Turn them back into line breaks.
const unescape = (v) => String(v).replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n');

// Every label sits above its value. Blank fields are skipped, so you can send as few as you like.
const fields = [
  ['Name', b.name],
  ['Email', b.email],
  ['Phone', b.phone],
  ['Booked For', b.booked],
  ['With', b.with],
  ['Calendar', b.calendar],
  ['Notes', b.notes]
];

const sections = fields
  .filter(([, v]) => !isBlank(v))
  .map(([k, v]) => `*${k}*\n${unescape(v)}`)
  .join('\n\n');

const heading = `📅 *${b.title || 'Strategy Call Booked'}*`;

// Send {"message": "..."} instead to skip the template and post your own text.
const message = b.message || (sections ? `${heading}\n\n${sections}` : heading);

// Recipient: "to" in the body wins, otherwise WHATSAPP_TO from .env.
// Accepts 64211234567@c.us, a group id ...@g.us, or a plain number like +64 21 123 4567.
let to = String(b.to || $env.WHATSAPP_TO || '').trim();
if (to && !to.includes('@')) to = to.replace(/\D/g, '') + '@c.us';
if (!to) throw new Error('No recipient: set WHATSAPP_TO in .env or send "to" in the body');

return [{ json: { message, chatId: to } }];
